14	/// Complete the given command, shell-agnostic
15	pub fn complete(
16	    cmd: &mut clap::Command,
17	    args: Vec<OsString>,
18	    arg_index: usize,
19	    current_dir: Option<&std::path::Path>,
20	) -> Result<Vec<CompletionCandidate>, std::io::Error> {
21	    debug!("complete: args={args:?}, arg_index={arg_index:?}, current_dir={current_dir:?}");
22	    cmd.build();
23	
24	    let raw_args = clap_lex::RawArgs::new(args);
25	    let mut cursor = raw_args.cursor();
26	    let mut target_cursor = raw_args.cursor();
27	    raw_args.seek(
28	        &mut target_cursor,
29	        clap_lex::SeekFrom::Start(arg_index as u64),
30	    );
31	    // As we loop, `cursor` will always be pointing to the next item
32	    raw_args.next_os(&mut target_cursor);
33	    debug!("complete: target_cursor={target_cursor:?}");
34	
35	    let mut current_cmd = &*cmd;
36	    if cmd.is_multicall_set() {
37	        // A multicall executable dispatches on the file name of argv0 (the
38	        // "applet"), falling back to the first argument when invoked through
39	        // its canonical or an unrecognized name, e.g. `busybox inspect`.
40	        let applet = raw_args
41	            .next_os(&mut cursor)
42	            .and_then(|argv0| std::path::Path::new(argv0).file_stem().map(OsStr::to_owned));
43	        if let Some(applet) = applet.as_deref().and_then(OsStr::to_str) {
44	            if let Some(subcmd) = cmd.find_subcommand(applet) {
45	                debug!("complete: multicall applet={applet:?}");
46	                current_cmd = subcmd;
47	            } else {
48	                // Unknown applet name: only continue when the next argument
49	                // names a known applet; otherwise there is nothing to complete.
50	                let mut peek = cursor.clone();
51	                let is_launcher = raw_args
52	                    .next_os(&mut peek)
53	                    .and_then(OsStr::to_str)
54	                    .is_some_and(|next| cmd.find_subcommand(next).is_some());
55	                if !is_launcher {
56	                    debug!("complete: unrecognized multicall applet={applet:?}");
57	                    return Ok(Vec::new());
58	                }
59	            }
60	        }
61	    } else if !cmd.is_no_binary_name_set() {
62	        raw_args.next_os(&mut cursor);
63	    }
64	    let mut pos_index = 1;
65	    let mut is_escaped = false;
66	    let mut next_state = ParseState::ValueDone;
67	    while let Some(arg) = raw_args.next(&mut cursor) {
68	        let current_state = next_state;
69	        next_state = ParseState::ValueDone;
70	        debug!(
71	            "complete::next: arg={:?}, current_state={current_state:?}, cursor={cursor:?}",
72	            arg.to_value_os(),
73	        );
74	        if cursor == target_cursor {
75	            return complete_arg(
76	                &arg,
77	                current_cmd,
78	                current_dir,
79	                pos_index,
80	                is_escaped,
81	                current_state,
82	            );
83	        }
84	
85	        if let Ok(value) = arg.to_value() {
86	            if let Some(next_cmd) = current_cmd.find_subcommand(value) {
87	                current_cmd = next_cmd;
88	                pos_index = 1;
89	                continue;
90	            }
91	        }
92	
93	        if is_escaped {
94	            (next_state, pos_index) =
95	                parse_positional(current_cmd, pos_index, is_escaped, current_state);
96	        } else if arg.is_escape() {
97	            is_escaped = true;
98	        } else if opt_allows_hyphen(&current_state, &arg) {
99	            match current_state {
100	                ParseState::Opt((opt, count)) => next_state = parse_opt_value(opt, count),
101	                _ => unreachable!("else branch is only reachable in Opt state"),
102	            }
103	        } else if let Some((flag, value)) = arg.to_long() {
104	            if let Ok(flag) = flag {
105	                let opt = current_cmd.get_arguments().find(|a| {
106	                    let longs = a.get_long_and_visible_aliases();
107	                    let is_find = longs.map(|v| {
108	                        let mut iter = v.into_iter();
109	                        let s = iter.find(|s| *s == flag);
110	                        s.is_some()
111	                    });
112	                    is_find.unwrap_or(false)
113	                });
114	
115	                if let Some(opt) = opt {
116	                    if opt.get_num_args().expect("built").takes_values() && value.is_none() {
117	                        next_state = ParseState::Opt((opt, 1));
118	                    };
119	                } else if pos_allows_hyphen(current_cmd, pos_index) {
120	                    (next_state, pos_index) =
121	                        parse_positional(current_cmd, pos_index, is_escaped, current_state);
122	                } else {
123	                    debug!("complete: unknown flag={flag:?}");
124	                    return Ok(Vec::new());
125	                }
126	            }
127	        } else if let Some(short) = arg.to_short() {
128	            let (_, takes_value_opt, mut short) = parse_shortflags(current_cmd, short);
129	            if let Some(opt) = takes_value_opt {
130	                if short.next_value_os().is_none() {
131	                    next_state = ParseState::Opt((opt, 1));
132	                }
133	            } else if pos_allows_hyphen(current_cmd, pos_index) {
134	                (next_state, pos_index) =
135	                    parse_positional(current_cmd, pos_index, is_escaped, current_state);
136	            }
137	        } else {
138	            match current_state {
139	                ParseState::ValueDone | ParseState::Pos(..) => {
140	                    if current_cmd
141	                        .get_positionals()
142	                        .all(|p| p.get_index() != Some(pos_index))
143	                    {
144	                        debug!("complete: unrecognized argument={:?}", arg.to_value_os());
145	                        return Ok(Vec::new());
146	                    }
147	                    (next_state, pos_index) =
148	                        parse_positional(current_cmd, pos_index, is_escaped, current_state);
149	                }
150	                ParseState::Opt((opt, count)) => next_state = parse_opt_value(opt, count),
151	            }
152	        }
153	    }
154	
155	    Err(std::io::Error::other("no completion generated"))
156	}
157	
158	#[derive(Debug, PartialEq, Eq, Clone)]
159	enum ParseState<'a> {
160	    /// Parsing a value done, there is no state to record.
161	    ValueDone,
162	
163	    /// Parsing a positional argument after `--`. `Pos(pos_index`, `takes_num_args`)
164	    Pos((usize, usize)),
165	
166	    /// Parsing a optional flag argument
167	    Opt((&'a clap::Arg, usize)),
168	}
169	
170	fn complete_arg(
171	    arg: &clap_lex::ParsedArg<'_>,
172	    cmd: &clap::Command,
173	    current_dir: Option<&std::path::Path>,
174	    pos_index: usize,
175	    is_escaped: bool,
176	    state: ParseState<'_>,
177	) -> Result<Vec<CompletionCandidate>, std::io::Error> {
178	    debug!(
179	        "complete_arg: arg={:?}, cmd={:?}, current_dir={:?}, pos_index={:?}, state={:?}",
180	        arg,
181	        cmd.get_name(),
182	        current_dir,
183	        pos_index,
184	        state
185	    );
186	    let mut completions = Vec::<CompletionCandidate>::new();
187	
188	    match state {
189	        ParseState::ValueDone => {
190	            if let Ok(value) = arg.to_value() {
191	                completions.extend(complete_subcommand(value, cmd));
192	            }
193	
194	            if let Some(positional) = cmd
195	                .get_positionals()
196	                .find(|p| p.get_index() == Some(pos_index))
197	            {
198	                completions.extend(complete_arg_value(
199	                    arg.to_value(),
200	                    positional,
201	                    current_dir,
202	                    0,
203	                ));
204	            }
205	            if !is_escaped {
206	                completions.extend(complete_option(arg, cmd, current_dir));
207	            }
208	        }
209	        ParseState::Pos((_, num_arg)) => {
210	            if let Some(positional) = cmd
211	                .get_positionals()
212	                .find(|p| p.get_index() == Some(pos_index))
213	            {
214	                completions.extend(complete_arg_value(
215	                    arg.to_value(),
216	                    positional,
217	                    current_dir,
218	                    num_arg.saturating_sub(1),
219	                ));
220	                if !is_escaped
221	                    && positional
222	                        .get_num_args()
223	                        .is_some_and(|num_args| num_arg >= num_args.min_values())
224	                {
225	                    completions.extend(complete_option(arg, cmd, current_dir));
226	                }
227	            }
228	        }
229	        ParseState::Opt((opt, count)) => {
230	            completions.extend(complete_arg_value(
231	                arg.to_value(),
232	                opt,
233	                current_dir,
234	                count.saturating_sub(1),
235	            ));
236	            let min = opt.get_num_args().map(|r| r.min_values()).unwrap_or(0);
237	            if count > min {
238	                // Also complete this raw_arg as a positional argument, flags, options and subcommand.
239	                completions.extend(complete_arg(
240	                    arg,
241	                    cmd,
242	                    current_dir,
243	                    pos_index,
244	                    is_escaped,
245	                    ParseState::ValueDone,
246	                )?);
247	            }
248	        }
249	    }
250	    if completions.iter().any(|a| !a.is_hide_set()) {
251	        completions.retain(|a| !a.is_hide_set());
252	    }
253	    let mut seen_ids = std::collections::HashSet::new();
254	    completions.retain(move |a| {
255	        if let Some(id) = a.get_id().cloned() {
256	            seen_ids.insert(id)
257	        } else {
258	            true
259	        }
260	    });
261	
262	    let mut tags = Vec::new();
263	    for candidate in &completions {
264	        let tag = candidate.get_tag().cloned();
265	        if !tags.contains(&tag) {
266	            tags.push(tag);
267	        }
268	    }
269	    completions.sort_by_key(|c| {
270	        (
271	            tags.iter().position(|t| c.get_tag() == t.as_ref()),
272	            c.get_display_order(),
273	        )
274	    });
275	
276	    Ok(completions)
277	}
278	
279	fn complete_option(
280	    arg: &clap_lex::ParsedArg<'_>,
281	    cmd: &clap::Command,
282	    current_dir: Option<&std::path::Path>,
283	) -> Vec<CompletionCandidate> {
284	    debug!("complete_option: arg={arg:?}, current_dir={current_dir:?}");
285	    let mut completions = Vec::<CompletionCandidate>::new();
286	    if arg.is_empty() {
287	        completions.extend(longs_and_visible_aliases(cmd));
288	        completions.extend(hidden_longs_aliases(cmd));
289	
290	        let dash_or_arg = if arg.is_empty() {
291	            "-".into()
292	        } else {
293	            arg.to_value_os().to_string_lossy()
294	        };
295	        completions.extend(
296	            shorts_and_visible_aliases(cmd)
297	                .into_iter()
298	                .map(|comp| comp.add_prefix(dash_or_arg.to_string())),
299	        );
300	    } else if arg.is_stdio() {
301	        // HACK: Assuming knowledge of is_stdio
302	        let dash_or_arg = if arg.is_empty() {
303	            "-".into()
304	        } else {
305	            arg.to_value_os().to_string_lossy()
306	        };
307	        completions.extend(
308	            shorts_and_visible_aliases(cmd)
309	                .into_iter()
310	                .map(|comp| comp.add_prefix(dash_or_arg.to_string())),
311	        );
312	
313	        completions.extend(longs_and_visible_aliases(cmd));
314	        completions.extend(hidden_longs_aliases(cmd));
315	    } else if arg.is_escape() {
316	        // HACK: Assuming knowledge of is_escape
317	        completions.extend(longs_and_visible_aliases(cmd));
318	        completions.extend(hidden_longs_aliases(cmd));
319	    } else if let Some((flag, value)) = arg.to_long() {
320	        if let Ok(flag) = flag {
321	            if let Some(value) = value {
322	                if let Some(arg) = cmd.get_arguments().find(|a| a.get_long() == Some(flag)) {
323	                    completions.extend(
324	                        complete_arg_value(value.to_str().ok_or(value), arg, current_dir, 0)
325	                            .into_iter()
326	                            .map(|comp| comp.add_prefix(format!("--{flag}="))),
327	                    );
328	                }
329	            } else {
330	                completions.extend(
331	                    longs_and_visible_aliases(cmd)
332	                        .into_iter()
333	                        .filter(|comp| comp.get_value().starts_with(format!("--{flag}").as_str())),
334	                );
335	                completions.extend(
336	                    hidden_longs_aliases(cmd)
337	                        .into_iter()
338	                        .filter(|comp| comp.get_value().starts_with(format!("--{flag}").as_str())),
339	                );
340	            }
341	        }
342	    } else if let Some(short) = arg.to_short() {
343	        if !short.is_negative_number() {
344	            // Find the first takes_values option.
345	            let (leading_flags, takes_value_opt, mut short) = parse_shortflags(cmd, short);
346	
347	            // Clone `short` to `peek_short` to peek whether the next flag is a `=`.
348	            if let Some(opt) = takes_value_opt {
349	                let mut peek_short = short.clone();
350	                let has_equal = if let Some(Ok('=')) = peek_short.next_flag() {
351	                    short.next_flag();
352	                    true
353	                } else {
354	                    false
355	                };
356	
357	                let value = short.next_value_os().unwrap_or(OsStr::new(""));
358	                completions.extend(
359	                    complete_arg_value(value.to_str().ok_or(value), opt, current_dir, 0)
360	                        .into_iter()
361	                        .map(|comp| {
362	                            let sep = if has_equal { "=" } else { "" };
363	                            comp.add_prefix(format!("-{leading_flags}{sep}"))
364	                        }),
365	                );
366	            } else {
367	                completions.extend(
368	                    shorts_and_visible_aliases(cmd)
369	                        .into_iter()
370	                        .map(|comp| comp.add_prefix(format!("-{leading_flags}"))),
371	                );
372	            }
373	        }
374	    }
375	    debug!("complete_option: completions={completions:?}");
376	    completions
377	}
378	
379	fn complete_arg_value(
380	    value: Result<&str, &OsStr>,
381	    arg: &clap::Arg,
382	    current_dir: Option<&std::path::Path>,
383	    arg_index: usize,
384	) -> Vec<CompletionCandidate> {
385	    let mut values = Vec::new();
386	    debug!("complete_arg_value: arg={arg:?}, value={value:?}, arg_index={arg_index:?}");
387	
388	    let (prefix, value) =
389	        rsplit_delimiter(value, arg.get_value_delimiter()).unwrap_or((None, value));
390	
391	    let value_os = match value {
392	        Ok(value) => OsStr::new(value),
393	        Err(value_os) => value_os,
394	    };
395	
396	    if let Some(completer) = arg.get::<ArgValueCompleter>() {
397	        values.extend(completer.complete_at(arg_index, value_os));
398	    } else if let Some(completer) = arg.get::<ArgValueCandidates>() {
399	        values.extend(complete_value_candidates(
400	            value_os,
401	            completer.value_candidates(),
402	        ));
403	    } else if let Some(possible_values) = possible_values(arg) {
404	        if let Ok(value) = value {
405	            values.extend(complete_candidates_str(
406	                value,
407	                possible_value_candidates(possible_values),
408	            ));
409	        }
410	    } else {
411	        match arg.get_value_hint() {
412	            clap::ValueHint::Unknown | clap::ValueHint::Other => {
413	                // Should not complete
414	            }
415	            clap::ValueHint::AnyPath => {
416	                values.extend(complete_path(value_os, current_dir, &|_| true));
417	            }
418	            clap::ValueHint::FilePath => {
419	                values.extend(complete_path(value_os, current_dir, &|p| p.is_file()));
420	            }
421	            clap::ValueHint::DirPath => {
422	                values.extend(complete_path(value_os, current_dir, &|p| p.is_dir()));
423	            }
424	            clap::ValueHint::ExecutablePath => {
425	                use is_executable::IsExecutable;
426	                values.extend(complete_path(value_os, current_dir, &|p| p.is_executable()));
427	            }
428	            clap::ValueHint::CommandName
429	            | clap::ValueHint::CommandString
430	            | clap::ValueHint::CommandWithArguments
431	            | clap::ValueHint::Username
432	            | clap::ValueHint::Hostname
433	            | clap::ValueHint::Url
434	            | clap::ValueHint::EmailAddress => {
435	                // No completion implementation
436	            }
437	            _ => {
438	                // Safe-ish fallback
439	                values.extend(complete_path(value_os, current_dir, &|_| true));
440	            }
441	        }
442	
443	        values.sort();
444	    }
445	
446	    if let Some(prefix) = prefix {
447	        values = values
448	            .into_iter()
449	            .map(|comp| comp.add_prefix(prefix))
450	            .collect();
451	    }
452	    values = values
453	        .into_iter()
454	        .map(|comp| {
455	            if comp.get_tag().is_some() {
456	                comp
457	            } else {
458	                comp.tag(Some(arg.to_string().into()))
459	            }
460	        })
461	        .collect();
462	
463	    debug!("complete_arg_value: values={values:?}");
464	    values
465	}
466	
467	fn rsplit_delimiter<'s, 'o>(
468	    value: Result<&'s str, &'o OsStr>,
469	    delimiter: Option<char>,
470	) -> Option<(Option<&'s str>, Result<&'s str, &'o OsStr>)> {
471	    let delimiter = delimiter?;
472	    let value = value.ok()?;
473	    let pos = value.rfind(delimiter)?;
474	    let (prefix, value) = value.split_at(pos + delimiter.len_utf8());
475	    Some((Some(prefix), Ok(value)))
476	}
477	
478	fn complete_value_candidates(
479	    value: &OsStr,
480	    completer: &dyn ValueCandidates,
481	) -> Vec<CompletionCandidate> {
482	    debug!("complete_value_candidates: value={value:?}");
483	
484	    let mut values = completer.candidates();
485	    values.retain(|comp| comp.get_value().starts_with(&value.to_string_lossy()));
486	    values
487	}
488	
489	fn complete_candidates_str(
490	    value: &str,
491	    mut values: Vec<CompletionCandidate>,
492	) -> Vec<CompletionCandidate> {
493	    debug!("complete_candidates_str: value={value:?}");
494	
495	    values.retain(|comp| comp.get_value().starts_with(value));
496	    values
497	}
498	
499	fn complete_value_candidates_str(
500	    value: &str,
501	    completer: &dyn ValueCandidates,
502	) -> Vec<CompletionCandidate> {
503	    debug!("complete_value_candidates_str: value={value:?}");
504	
505	    complete_candidates_str(value, completer.candidates())
506	}
507	
508	fn complete_subcommand(value: &str, cmd: &clap::Command) -> Vec<CompletionCandidate> {
509	    debug!(
510	        "complete_subcommand: cmd={:?}, value={:?}",
511	        cmd.get_name(),
512	        value
513	    );
514	
515	    let mut scs: Vec<CompletionCandidate> = subcommands(cmd)
516	        .into_iter()
517	        .filter(|x| x.get_value().starts_with(value))
518	        .collect();
519	    if cmd.is_allow_external_subcommands_set() {
520	        let external_completer = cmd.get::<SubcommandCandidates>();
521	        if let Some(completer) = external_completer {
522	            scs.extend(complete_value_candidates_str(
523	                value,
524	                completer.value_candidates(),
525	            ));
526	        }
527	    }
528	
529	    scs.sort();
530	    scs.dedup();
531	    scs
532	}
