534	/// Gets all the long options, their visible aliases and flags of a [`clap::Command`] with formatted `--` prefix.
535	/// Includes `help` and `version` depending on the [`clap::Command`] settings.
536	fn longs_and_visible_aliases(p: &clap::Command) -> Vec<CompletionCandidate> {
537	    debug!("longs: name={}", p.get_name());
538	
539	    p.get_arguments()
540	        .filter_map(|a| {
541	            a.get_long_and_visible_aliases().map(|longs| {
542	                longs
543	                    .into_iter()
544	                    .map(|s| populate_arg_candidate(CompletionCandidate::new(format!("--{s}")), a))
545	            })
546	        })
547	        .flatten()
548	        .collect()
549	}
550	
551	/// Gets all the long hidden aliases and flags of a [`clap::Command`].
552	fn hidden_longs_aliases(p: &clap::Command) -> Vec<CompletionCandidate> {
553	    debug!("longs: name={}", p.get_name());
554	
555	    p.get_arguments()
556	        .filter_map(|a| {
557	            a.get_aliases().map(|longs| {
558	                longs.into_iter().map(|s| {
559	                    populate_arg_candidate(CompletionCandidate::new(format!("--{s}")), a).hide(true)
560	                })
561	            })
562	        })
563	        .flatten()
564	        .collect()
565	}
566	
567	/// Gets all the short options, their visible aliases and flags of a [`clap::Command`].
568	/// Includes `h` and `V` depending on the [`clap::Command`] settings.
569	fn shorts_and_visible_aliases(p: &clap::Command) -> Vec<CompletionCandidate> {
570	    debug!("shorts: name={}", p.get_name());
571	
572	    p.get_arguments()
573	        .filter_map(|a| {
574	            a.get_short_and_visible_aliases().map(|shorts| {
575	                shorts.into_iter().map(|s| {
576	                    populate_arg_candidate(CompletionCandidate::new(s.to_string()), a).help(
577	                        a.get_help()
578	                            .cloned()
579	                            .or_else(|| a.get_long().map(|long| format!("--{long}").into())),
580	                    )
581	                })
582	            })
583	        })
584	        .flatten()
585	        .collect()
586	}
587	
588	fn populate_arg_candidate(candidate: CompletionCandidate, arg: &clap::Arg) -> CompletionCandidate {
589	    candidate
590	        .help(arg.get_help().cloned())
591	        .id(Some(format!("arg::{}", arg.get_id())))
592	        .tag(Some(
593	            arg.get_help_heading()
594	                .unwrap_or("Options")
595	                .to_owned()
596	                .into(),
597	        ))
598	        .display_order(Some(arg.get_display_order()))
599	        .hide(arg.is_hide_set())
600	}
601	
602	/// Get the possible values for completion
603	fn possible_values(
604	    a: &clap::Arg,
605	) -> Option<Box<dyn Iterator<Item = clap::builder::PossibleValue> + '_>> {
606	    if !a.get_num_args().expect("built").takes_values() {
607	        None
608	    } else {
609	        a.get_value_parser().possible_values()
610	    }
611	}
612	
613	/// Gets subcommands of [`clap::Command`] in the form of `("name", "bin_name")`.
614	///
615	/// Subcommand `rustup toolchain install` would be converted to
616	/// `("install", "rustup toolchain install")`.
617	fn subcommands(p: &clap::Command) -> Vec<CompletionCandidate> {
618	    debug!("subcommands: name={}", p.get_name());
619	    debug!("subcommands: Has subcommands...{:?}", p.has_subcommands());
620	    p.get_subcommands()
621	        .flat_map(|sc| {
622	            sc.get_name_and_visible_aliases()
623	                .into_iter()
624	                .map(|s| populate_command_candidate(CompletionCandidate::new(s.to_owned()), p, sc))
625	                .chain(sc.get_aliases().map(|s| {
626	                    populate_command_candidate(CompletionCandidate::new(s.to_owned()), p, sc)
627	                        .hide(true)
628	                }))
629	        })
630	        .collect()
631	}
632	
633	fn populate_command_candidate(
634	    candidate: CompletionCandidate,
635	    cmd: &clap::Command,
636	    subcommand: &clap::Command,
637	) -> CompletionCandidate {
638	    candidate
639	        .help(subcommand.get_about().cloned())
640	        .id(Some(format!("command::{}", subcommand.get_name())))
641	        .tag(Some(
642	            cmd.get_subcommand_help_heading()
643	                .unwrap_or("Commands")
644	                .to_owned()
645	                .into(),
646	        ))
647	        .display_order(Some(subcommand.get_display_order()))
648	        .hide(subcommand.is_hide_set())
649	}
650	
651	/// Parse the short flags and find the first `takes_values` option.
652	fn parse_shortflags<'c, 's>(
653	    cmd: &'c clap::Command,
654	    mut short: clap_lex::ShortFlags<'s>,
655	) -> (String, Option<&'c clap::Arg>, clap_lex::ShortFlags<'s>) {
656	    let takes_value_opt;
657	    let mut leading_flags = String::new();
658	    // Find the first takes_values option.
659	    loop {
660	        match short.next_flag() {
661	            Some(Ok(opt)) => {
662	                leading_flags.push(opt);
663	                let opt = cmd.get_arguments().find(|a| {
664	                    let shorts = a.get_short_and_visible_aliases();
665	                    let is_find = shorts.map(|v| {
666	                        let mut iter = v.into_iter();
667	                        let c = iter.find(|c| *c == opt);
668	                        c.is_some()
669	                    });
670	                    is_find.unwrap_or(false)
671	                });
672	                if opt
673	                    .map(|o| o.get_num_args().expect("built").takes_values())
674	                    .unwrap_or(false)
675	                {
676	                    takes_value_opt = opt;
677	                    break;
678	                }
679	            }
680	            Some(Err(_)) | None => {
681	                takes_value_opt = None;
682	                break;
683	            }
684	        }
685	    }
686	
687	    (leading_flags, takes_value_opt, short)
688	}
689	
690	/// Parse the positional arguments. Return the new state and the new positional index.
691	fn parse_positional<'a>(
692	    cmd: &clap::Command,
693	    pos_index: usize,
694	    is_escaped: bool,
695	    state: ParseState<'a>,
696	) -> (ParseState<'a>, usize) {
697	    let pos_arg = cmd
698	        .get_positionals()
699	        .find(|p| p.get_index() == Some(pos_index));
700	    let num_args = pos_arg
701	        .and_then(|a| a.get_num_args().map(|r| r.max_values()))
702	        .unwrap_or(1);
703	
704	    let update_state_with_new_positional = |pos_index| -> (ParseState<'a>, usize) {
705	        if num_args > 1 {
706	            (ParseState::Pos((pos_index, 1)), pos_index)
707	        } else {
708	            if is_escaped {
709	                (ParseState::Pos((pos_index, 1)), pos_index + 1)
710	            } else {
711	                (ParseState::ValueDone, pos_index + 1)
712	            }
713	        }
714	    };
715	    match state {
716	        ParseState::ValueDone => {
717	            update_state_with_new_positional(pos_index)
718	        },
719	        ParseState::Pos((prev_pos_index, num_arg)) => {
720	            if prev_pos_index == pos_index {
721	                if num_arg + 1 < num_args {
722	                    (ParseState::Pos((pos_index, num_arg + 1)), pos_index)
723	                } else {
724	                    if is_escaped {
725	                        (ParseState::Pos((pos_index, 1)), pos_index + 1)
726	                    } else {
727	                        (ParseState::ValueDone, pos_index + 1)
728	                    }
729	                }
730	            } else {
731	                update_state_with_new_positional(pos_index)
732	            }
733	        }
734	        ParseState::Opt(..) => unreachable!(
735	            "This branch won't be hit,
736	            because ParseState::Opt should not be seen as a positional argument and passed to this function."
737	        ),
738	    }
739	}
740	
741	/// Parse optional flag argument. Return new state
742	fn parse_opt_value(opt: &clap::Arg, count: usize) -> ParseState<'_> {
743	    let range = opt.get_num_args().expect("built");
744	    let max = range.max_values();
745	    if count < max {
746	        ParseState::Opt((opt, count + 1))
747	    } else {
748	        ParseState::ValueDone
749	    }
750	}
751	
752	fn pos_allows_hyphen(cmd: &clap::Command, pos_index: usize) -> bool {
753	    cmd.get_positionals()
754	        .find(|a| a.get_index() == Some(pos_index))
755	        .map(|p| p.is_allow_hyphen_values_set())
756	        .unwrap_or(false)
757	}
758	
759	fn opt_allows_hyphen(state: &ParseState<'_>, arg: &clap_lex::ParsedArg<'_>) -> bool {
760	    let val = arg.to_value_os();
761	    if val.starts_with("-") {
762	        if let ParseState::Opt((opt, _)) = state {
763	            return opt.is_allow_hyphen_values_set();
764	        }
765	    }
766	
767	    false
768	}
