12	/// Extend [`Arg`][clap::Arg] with a completer
13	///
14	/// # Example
15	///
16	/// ```rust
17	/// use clap::Parser;
18	/// use clap_complete::engine::{ArgValueCompleter, CompletionCandidate};
19	///
20	/// fn custom_completer(current: &std::ffi::OsStr) -> Vec<CompletionCandidate> {
21	///     let mut completions = vec![];
22	///     let Some(current) = current.to_str() else {
23	///         return completions;
24	///     };
25	///
26	///     if "foo".starts_with(current) {
27	///         completions.push(CompletionCandidate::new("foo"));
28	///     }
29	///     if "bar".starts_with(current) {
30	///         completions.push(CompletionCandidate::new("bar"));
31	///     }
32	///     if "baz".starts_with(current) {
33	///         completions.push(CompletionCandidate::new("baz"));
34	///     }
35	///     completions
36	/// }
37	///
38	/// #[derive(Debug, Parser)]
39	/// struct Cli {
40	///     #[arg(long, add = ArgValueCompleter::new(custom_completer))]
41	///     custom: Option<String>,
42	/// }
43	/// ```
44	#[derive(Clone)]
45	pub struct ArgValueCompleter(Arc<dyn ValueCompleter>);
46	
47	impl ArgValueCompleter {
48	    /// Create a new `ArgValueCompleter` with a custom completer
49	    pub fn new<C>(completer: C) -> Self
50	    where
51	        C: ValueCompleter + 'static,
52	    {
53	        Self(Arc::new(completer))
54	    }
55	
56	    /// Candidates that match `current`
57	    ///
58	    /// See [`CompletionCandidate`] for more information.
59	    pub fn complete(&self, current: &OsStr) -> Vec<CompletionCandidate> {
60	        self.0.complete(current)
61	    }
62	
63	    /// Candidates that match `current` at `arg_index` within the current occurrence.
64	    ///
65	    /// `arg_index` is the position of the value being completed within an
66	    /// argument's [`num_args`][clap::Arg::num_args] range, starting at `0`.
67	    /// This lets a completer return different candidates for each value of a
68	    /// multi-value argument (for example, a remote name first and a branch
69	    /// name second for `--set-upstream <REMOTE> <BRANCH>`).
70	    ///
71	    /// `arg_index` is unaffected by [`value_delimiter`][clap::Arg::value_delimiter]:
72	    /// it counts shell arguments, not delimiter-separated values.
73	    ///
74	    /// See [`CompletionCandidate`] for more information.
75	    pub fn complete_at(&self, arg_index: usize, current: &OsStr) -> Vec<CompletionCandidate> {
76	        self.0.complete_at(arg_index, current)
77	    }
78	}
